      en: ["Opened: 2016.", "Area: 200 hectares.", "Anchor investor: KHAN (South Korea).", "Total investment: $120 million.", "Jobs created: 3,000.", "Tax holiday duration: 10 years."],
      es: ["Año de fundación: 2016.", "Superficie: 200 hectáreas.", "Empresas instaladas: 15.", "Inversiones: 120 millones de USD.", "Puestos de trabajo: 3.000.", "Exención fiscal: 10 años."],
      pt: ["Ano de fundação: 2016.", "Área: 200 hectares.", "Empresas instaladas: 15.", "Investimentos: 120 milhões de USD.", "Empregos: 3.000.", "Isenção fiscal: 10 anos."],
