      de: ["Das Zementwerk wurde im Jahr 1926 offiziell gegründet.", "Es wird heute von der HeidelbergCement Georgia betrieben.", "Im Jahr 2018 wurde eine neue Trockenlinie für 100 Millionen USD gebaut.", "Die Fabrik produziert verschiedene Zementsorten für Großbauprojekte.", "Sie befindet sich direkt an der zentralen Ost-West-Eisenbahnlinie.", "Das Werk nutzt Kalkstein aus nahegelegenen Steinbrüchen in Shida Kartli."],
      hu: ["A cementgyárat hivatalosan 1926-ban alapították.", "Jelenleg a HeidelbergCement Georgia vállalat üzemelteti.", "2018-ban egy új száraz technológiás sort építettek 100 millió dollárból.", "A gyár különböző típusú cementet állít elő nagyberuházásokhoz.", "A létesítmény közvetlenül a központi kelet-nyugati vasútvonal mellett fekszik.", "Az üzem a közeli Shida Kartli-i kőfejtőkből származó mészkövet használja."],
      ro: ["Fabrica de ciment a fost fondată oficial în anul 1926.", "În prezent, este operată de HeidelbergCement Georgia.", "În 2018, a fost construită o nouă linie de producție uscată pentru 100 mil. USD.", "Fabrica produce diverse tipuri de ciment pentru proiecte majore de construcții.", "Se află direct pe linia de cale ferată centrală Est-Vest.", "Unitatea utilizează calcar din carierele din apropiere, situate în Shida Kartli."],
      en: ["The cement plant was officially established in 1926.", "It is currently operated by HeidelbergCement Georgia.", "A new dry-line production facility was built in 2018 for 100 million USD.", "The factory produces various grades of cement for large-scale projects.", "It is located directly on Georgia's central East-West railway line.", "The plant sources limestone from nearby quarries in Shida Kartli."],
      es: ["Capacidad anual: 1,5 millones de toneladas.", "Empleados: 600.", "Año de construcción: 1960.", "Consumo de carbón por tonelada de clínker: 100 kg.", "Emisiones de CO2: 1,2 millones de toneladas anuales.", "Puesta en marcha del nuevo molino: 2020."],
      pt: ["Capacidade anual: 1,5 milhões de toneladas.", "Funcionários: 600.", "Ano de construção: 1960.", "Consumo de carvão por tonelada de clínquer: 100 kg.", "Emissões de CO2: 1,2 milhões de toneladas por ano.", "Início de operação do novo moinho: 2020."],
      fr: ["Capacité annuelle : 1,5 million de tonnes.", "Employés : 600.", "Année de construction : 1960.", "Consommation de charbon par tonne de clinker : 100 kg.", "Émissions de CO2 : 1,2 million de tonnes par an.", "Mise en service du nouveau broyeur : 2020."],
