    descriptionAdvanced: {
      de: "Das Samgori-Ölfeld, östlich von Tiflis in der Region Kachetien gelegen, stellt eine der bedeutendsten Kohlenwasserstoff-Lagerstätten Georgiens dar. Entdeckt im Jahr 1974, löste das Feld einen bedeutenden Aufschwung in der lokalen Energiewirtschaft aus und erreichte in den frühen 1980er Jahren sein Produktionsmaximum. Die geologische Struktur ist durch komplexe vulkanogen-sedimentäre Gesteine des Eozäns geprägt, was die Extraktion technisch anspruchsvoll macht. Über Jahrzehnte hinweg war Samgori die primäre Quelle für die inländische Rohölförderung und versorgte die Raffinerien des Landes. In der postsowjetischen Ära wurden moderne Methoden wie die Horizontalbohrung eingeführt, um die verbleibenden Reserven effizienter zu nutzen. Trotz des natürlichen Rückgangs der Fördermengen bleibt das Feld ein strategisches Element der georgischen Energieinfrastruktur und dient als Basis für Forschungsprojekte im Bereich der tertiären Erdölförderung.",
      hu: "A Tbiliszitől keletre, Kakheti régióban található Samgori olajmező Grúzia egyik legfontosabb szénhidrogén-lelőhelye. Az 1974-ben felfedezett mező jelentős fellendülést hozott a helyi energiaiparban, és az 1980-as évek elején érte el termelési csúcsát. A terület geológiai szerkezetét összetett eocén kori vulkanogén-üledékes kőzetek jellemzik, ami technikailag kihívást jelent a kitermelés számára. Évtizedeken át a Samgori mező volt a hazai nyersolajtermelés elsődleges forrása, kiszolgálva az ország finomítóit. A posztszovjet korszakban olyan modern eljárásokat vezettek be, mint a vízszintes fúrás, hogy hatékonyabban használják ki a fennmaradó készleteket. A kitermelési volumen természetes csökkenése ellenére a mező továbbra is a grúz energetikai infrastruktúra stratégiai eleme, és bázisul szolgál a harmadlagos olajkitermeléssel kapcsolatos kutatási projektekhez.",
      ro: "Câmpul petrolifer Samgori, situat la est de Tbilisi în regiunea Kakheti, reprezintă unul dintre cele mai importante depozite de hidrocarburi din Georgia. Descoperit în anul 1974, acest câmp a declanșat o expansiune semnificativă în sectorul energetic local, atingând vârful de producție la începutul anilor 1980. Structura geologică este caracterizată de roci vulcanogen-sedimentare complexe din perioada eocenului, ceea ce face extracția dificilă din punct de vedere tehnic. Timp de decenii, Samgori a fost sursa primară de producție internă de țiței, alimentând rafinăriile țării. În epoca post-sovietică, au fost introduse metode moderne, precum forajul orizontal, pentru a exploata mai eficient rezervele rămase. În ciuda declinului natural al volumelor de extracție, câmpul rămâne un element strategic al infrastructurii energetice georgiene și servește drept bază pentru proiecte de cercetare în domeniul recuperării terțiare a petrolului.",
      en: "The Samgori oil field, located east of Tbilisi in the Kakheti region, represents one of Georgia's most significant hydrocarbon deposits. Discovered in 1974, the field triggered a major boost in the local energy industry and reached its production peak in the early 1980s. The geological structure is characterized by complex Eocene volcanogenic-sedimentary rocks, making extraction technically demanding. For decades, Samgori was the primary source for domestic crude oil production, supplying the country's refineries. In the post-Soviet era, modern methods such as horizontal drilling were introduced to utilize the remaining reserves more efficiently. Despite the natural decline in production volumes, the field remains a strategic element of the Georgian energy infrastructure and serves as a base for research projects in the field of enhanced oil recovery.",
      es: "El campo petrolífero de Samgori se encuentra en la región de Kvemo Kartli, a unos 30 km al sureste de Tbilisi. Fue descubierto en 1974 y comenzó su producción en 1976. El campo es operado por la Corporación de Petróleo y Gas de Georgia (GOGC). La extracción alcanzó su punto máximo en la década de 1980 con 1,5 millones de toneladas anuales, pero desde entonces ha descendido a unas 200.000 toneladas. Las reservas se estiman en 50 millones de toneladas, aunque las reservas recuperables son de solo 10 millones de toneladas. El petróleo tiene una densidad API de 35°. El yacimiento se encuentra a una profundidad de entre 2.500 y 3.000 metros. La extracción se realiza mediante inyección de agua. El campo abastece de crudo a la refinería de Batumi. La producción está en declive debido al envejecimiento de los pozos. Existen planes para métodos de recuperación terciaria para aumentar el rendimiento.",
      pt: "O campo petrolífero de Samgori está localizado na região de Kvemo Kartli, a cerca de 30 km a sudeste de Tbilisi. Foi descoberto em 1974 e entrou em produção em 1976. O campo é operado pela Georgian Oil and Gas Corporation (GOGC). A extração atingiu um pico de 1,5 milhões de toneladas por ano na década de 1980, mas desde então caiu para cerca de 200.000 toneladas. As reservas são estimadas em 50 milhões de toneladas, mas as reservas recuperáveis são de apenas 10 milhões de toneladas. O petróleo tem uma densidade API de 35°. O depósito está localizado a uma profundidade de 2.500 a 3.000 metros. A extração é feita por inundação de água. O campo fornece petróleo bruto à refinaria de Batumi. A produção está a diminuir à medida que os poços envelhecem. Existem planos para processos de recuperação terciária para aumentar o rendimento.",
      fr: "Le champ pétrolifère de Samgori est situé dans la région de Kvemo Kartli, à environ 30 km au sud-est de Tbilissi. Il a été découvert en 1974 et mis en production en 1976. Le champ est exploité par la Georgian Oil and Gas Corporation (GOGC). La production a atteint un sommet dans les années 1980 avec 1,5 million de tonnes par an, mais elle est depuis retombée à environ 200 000 tonnes. Les réserves sont estimées à 50 millions de tonnes, mais les réserves récupérables ne sont que de 10 millions de tonnes. Le pétrole a une densité API de 35°. Le gisement se situe à une profondeur de 2 500 à 3 000 mètres. L'extraction se fait par injection d'eau. Le champ approvisionne la raffinerie de Batoumi en pétrole brut. La production est en déclin car les puits vieillissent. Des projets de méthodes de récupération tertiaire existent pour augmenter le rendement.",
    },
